public sealed class WorkItem {public string id{get;set;} public string title{get;set;} public string projectPath{get;set;} public string details{get;set;} public string state{get;set;} public string updatedAt{get;set;} public string completedAt{get;set;}}
public sealed class WorkDocument {public int schemaVersion{get;set;} public long revision{get;set;} public string updatedAt{get;set;} public List<WorkItem> items{get;set;}}
public sealed class WorkPatch {public long expectedRevision{get;set;} public string id{get;set;} public string title{get;set;} public string projectPath{get;set;} public string details{get;set;}}
internal sealed class ChecklistStore {
    internal static readonly string FilePath=Path.Combine(AppData.Root,".local","current-work.json");
    readonly string file;readonly List<Entry> catalog;
    internal ChecklistStore(string path,List<Entry> entries){file=path;catalog=entries;}
    static void Require(bool ok,string message){if(!ok)throw new Exception(message);}
    static void Text(string value,int limit,string field,bool optional){Require((optional&&String.IsNullOrEmpty(value))||(!String.IsNullOrWhiteSpace(value)&&value.Length<=limit&&!value.Any(c=>Char.IsControl(c)&&c!='\n'&&c!='\r')),"Invalid checklist "+field+".");}
    void Project(string path){if(String.IsNullOrEmpty(path))return;Require(Path.IsPathRooted(path),"Project folder must be absolute.");string resolved=Path.GetFullPath(path).TrimEnd('\\','/');Require(catalog.Where(e=>e.section=="software"||e.section=="website"||e.section=="secondary").SelectMany(e=>e.targets).Any(t=>t.kind=="folder"&&String.Equals(Path.GetFullPath(t.path).TrimEnd('\\','/'),resolved,StringComparison.OrdinalIgnoreCase)),"Project folder must match a saved dashboard folder.");}
    void Validate(WorkDocument document){Require(document!=null&&document.schemaVersion==1&&document.revision>=0&&document.items!=null&&document.items.Count<=500,"Unsupported or invalid checklist document.");if(document.updatedAt!=null)AgentFeed.Time(document.updatedAt);var ids=new HashSet<string>(StringComparer.Ordinal);foreach(var item in document.items){Require(item!=null,"Invalid checklist item.");Text(item.id,100,"ID",false);Require(ids.Add(item.id),"Duplicate checklist ID.");Text(item.title,240,"title",false);Text(item.details,2000,"details",true);Project(item.projectPath);Require(item.state=="current"||item.state=="done","Invalid checklist state.");AgentFeed.Time(item.updatedAt);if(item.state=="done"){Require(item.completedAt!=null,"Done item is missing its completion date.");AgentFeed.Time(item.completedAt);}else Require(item.completedAt==null,"Current item has a completion date.");}}
    internal WorkDocument Read(){if(!File.Exists(file))return new WorkDocument{schemaVersion=1,revision=0,items=new List<WorkItem>()};using(var stream=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){Require(stream.Length<=2*1024*1024,"Checklist file is too large.");using(var reader=new StreamReader(stream)){var document=AppData.Json.Deserialize<WorkDocument>(reader.ReadToEnd());Validate(document);return document;}}}
    internal static string LockName(string path){using(var sha=SHA256.Create())return "Local\\LocalDashboardChecklist-"+BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(Path.GetFullPath(path).ToLowerInvariant()))).Replace("-","").Substring(0,24);}
    WorkDocument Edit(long expected,Action<WorkDocument> action){bool locked=false;using(var mutex=new Mutex(false,LockName(file))){try{try{locked=mutex.WaitOne(0);}catch(AbandonedMutexException){locked=true;}Require(locked,"Checklist is busy. Refresh and try again.");var document=Read();Require(document.revision==expected,"Checklist changed since this view was loaded. Refresh and try again; no changes were saved.");Require(document.revision<Int64.MaxValue,"Checklist revision limit reached.");action(document);document.revision++;document.updatedAt=DateTimeOffset.UtcNow.ToString("o");Validate(document);string json=SerializePreservingUnknown(document);Require(Encoding.UTF8.GetByteCount(json)<=2*1024*1024,"Checklist exceeds size limit.");Directory.CreateDirectory(Path.GetDirectoryName(file));string temporary=file+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllText(temporary,json,new UTF8Encoding(false));if(File.Exists(file))File.Replace(temporary,file,null);else File.Move(temporary,file);}finally{if(File.Exists(temporary))File.Delete(temporary);}return document;}finally{if(locked)mutex.ReleaseMutex();}}}
    string SerializePreservingUnknown(WorkDocument document){var raw=File.Exists(file)?AppData.Json.DeserializeObject(File.ReadAllText(file)) as Dictionary<string,object>:new Dictionary<string,object>();Require(raw!=null,"Invalid checklist document.");var oldItems=new Dictionary<string,Dictionary<string,object>>(StringComparer.Ordinal);object savedItems;if(raw.TryGetValue("items",out savedItems)&&savedItems is System.Collections.IEnumerable)foreach(object value in (System.Collections.IEnumerable)savedItems){var item=value as Dictionary<string,object>;if(item!=null&&item.ContainsKey("id"))oldItems[Convert.ToString(item["id"])]=item;}var output=new List<object>();foreach(var item in document.items){Dictionary<string,object> data;if(!oldItems.TryGetValue(item.id,out data))data=new Dictionary<string,object>();var known=(Dictionary<string,object>)AppData.Json.DeserializeObject(AppData.Json.Serialize(item));foreach(var pair in known)data[pair.Key]=pair.Value;output.Add(data);}raw["schemaVersion"]=document.schemaVersion;raw["revision"]=document.revision;raw["updatedAt"]=document.updatedAt;raw["items"]=output;return AppData.Json.Serialize(raw);}
    internal WorkDocument Upsert(WorkPatch patch){Require(patch!=null,"Missing checklist patch.");Text(patch.id,100,"ID",false);Text(patch.title,240,"title",false);Text(patch.details,2000,"details",true);Project(patch.projectPath);return Edit(patch.expectedRevision,document=>{var item=document.items.FirstOrDefault(i=>i.id==patch.id);if(item==null){item=new WorkItem{id=patch.id,state="current"};document.items.Add(item);}item.title=patch.title;item.projectPath=patch.projectPath;item.details=patch.details;item.updatedAt=DateTimeOffset.UtcNow.ToString("o");});}
    internal WorkDocument Complete(long expected,string id,bool done){return Edit(expected,document=>{var item=document.items.FirstOrDefault(i=>i.id==id);Require(item!=null,"Checklist item no longer exists.");item.state=done?"done":"current";item.updatedAt=DateTimeOffset.UtcNow.ToString("o");item.completedAt=done?item.updatedAt:null;});}
    internal static string Request(WorkDocument document,string profile=null){return "Quinn, please update my Current Work checklist from our current authorized work. Read the latest file first: "+(profile==null?FilePath:Path.Combine(profile,".local","current-work.json"))+"\r\nObserved revision: "+document.revision+".\r\nUse the versioned patch helper and expected-revision checks described in "+Path.Combine(AppData.Root,".dev","Current Work Contract.md")+". Preserve stable IDs and all user checkoffs/Done items. Do not import historical tasks, invent work, or overwrite the whole file. Refresh and retry if the revision changed.";}
    internal static void SelfTest(List<Entry> entries){string folder=Path.Combine(AppData.Root,".dev","Review","ChecklistTests");Directory.CreateDirectory(folder);string path=Path.Combine(folder,"current-work-test.json");if(File.Exists(path))File.Delete(path);var store=new ChecklistStore(path,entries);Require(store.Read().revision==0&&!File.Exists(path),"Missing checklist was not empty.");var patch=new WorkPatch{expectedRevision=0,id="test-item",title="Fixture only",projectPath=AppData.Root,details="Not published to the live checklist"};var added=store.Upsert(patch);Require(added.revision==1&&added.items.Count==1,"Add failed.");store.Complete(1,"test-item",true);patch.expectedRevision=1;bool conflict=false;try{store.Upsert(patch);}catch{conflict=true;}Require(conflict&&store.Read().revision==2&&store.Read().items[0].state=="done","Stale metadata lost a checkoff.");patch.expectedRevision=2;patch.title="Updated fixture";var edited=store.Upsert(patch);Require(edited.items[0].state=="done"&&edited.items[0].completedAt!=null,"Metadata restored completed work.");var restored=store.Complete(3,"test-item",false);Require(restored.revision==4&&restored.items[0].state=="current"&&restored.items[0].completedAt==null,"Restore failed.");using(var mutex=new Mutex(true,LockName(path))){bool busy=false;var worker=new Thread(()=>{try{store.Complete(4,"test-item",true);}catch(Exception error){busy=error.Message.Contains("busy");}});worker.Start();Require(worker.Join(5000)&&busy&&store.Read().revision==4,"Concurrent writer was not rejected.");mutex.ReleaseMutex();}var raw=(Dictionary<string,object>)AppData.Json.DeserializeObject(File.ReadAllText(path));raw["extraDocument"]=new Dictionary<string,object>{{"retain",true}};var rawItems=(object[])raw["items"];((Dictionary<string,object>)rawItems[0])["extraItem"]="retain me";File.WriteAllText(path,AppData.Json.Serialize(raw));store.Complete(4,"test-item",true);var retained=(Dictionary<string,object>)AppData.Json.DeserializeObject(File.ReadAllText(path));Require(retained.ContainsKey("extraDocument")&&((Dictionary<string,object>)((object[])retained["items"])[0])["extraItem"].ToString()=="retain me","Unknown data was lost.");string invalid="{\"schemaVersion\":99,\"revision\":4,\"items\":[]}";File.WriteAllText(path,invalid);bool rejected=false;try{store.Complete(5,"test-item",true);}catch{rejected=true;}Require(rejected&&File.ReadAllText(path)==invalid,"Invalid data was overwritten.");Require(Directory.GetFiles(folder,"*.tmp").Length==0,"Temporary files leaked.");Console.WriteLine("Checklist tests passed: empty initialization, persistence, completion/Done, metadata preserving checkoffs, stale revision rejection, restore, concurrent ownership and invalid-data and unknown-field preservation. No live items created.");}
}
internal sealed class CurrentWorkView:Panel {
    string assistantProfile; bool assistantView=true; readonly Button assistant=DashboardForm.LinkButton("Quinn work"),personal=DashboardForm.LinkButton("My checklist");
    readonly Label heading=new Label(),summary=new Label(),footnote=new Label();readonly Button current=DashboardForm.LinkButton("Current"),done=DashboardForm.LinkButton("Done"),ask=DashboardForm.LinkButton("Ask Quinn to update");readonly Panel rows=new Panel();readonly System.Windows.Forms.Timer timer=new System.Windows.Forms.Timer();ChecklistStore store;WorkDocument document;bool showDone,testing;string previous;
    internal CurrentWorkView(){BackColor=DashboardForm.Background;heading.Text="Current work";heading.Font=new Font("Segoe UI Variable Text",21.75f,FontStyle.Bold);heading.ForeColor=DashboardForm.Ink;heading.SetBounds(16,12,360,40);Controls.Add(heading);assistant.Click+=(s,e)=>{assistantView=true;LoadItems(true);};personal.Click+=(s,e)=>{assistantView=false;LoadItems(true);};Controls.Add(assistant);Controls.Add(personal);summary.ForeColor=DashboardForm.Muted;summary.UseMnemonic=false;Controls.Add(summary);current.Click+=(s,e)=>{showDone=false;LoadItems(true);};done.Click+=(s,e)=>{showDone=true;LoadItems(true);};Controls.Add(current);Controls.Add(done);rows.AutoScroll=true;rows.BackColor=BackColor;Controls.Add(rows);ask.Click+=(s,e)=>Ask();Controls.Add(ask);footnote.Text="Copies a request; send it in Quinn’s chat.";footnote.ForeColor=DashboardForm.Muted;Controls.Add(footnote);Resize+=(s,e)=>Position();timer.Interval=1500;timer.Tick+=(s,e)=>{if(Visible&&!assistantView)LoadItems(false);};timer.Start();}
    internal void Reload(List<Entry> entries){store=new ChecklistStore(ChecklistStore.FilePath,entries);LoadItems(true);}
    void Position(){assistant.SetBounds(16,56,140,34);personal.SetBounds(164,56,140,34);summary.SetBounds(16,94,Math.Max(80,Width-32),22);current.SetBounds(16,124,104,34);done.SetBounds(128,124,104,34);rows.SetBounds(0,172,Width,Math.Max(0,Height-260));ask.SetBounds(16,Math.Max(0,Height-80),Math.Max(100,Width-32),36);footnote.SetBounds(16,Math.Max(0,Height-39),Math.Max(80,Width-32),32);PositionRows();}
    void PositionRows(){if(assistantView)return;int y=0;Point offset=rows.AutoScrollPosition;foreach(Control row in rows.Controls){row.SetBounds(16+offset.X,y+offset.Y,Math.Max(120,rows.ClientSize.Width-32-SystemInformation.VerticalScrollBarWidth),row.Height);y+=row.Height+8;}rows.AutoScrollMinSize=new Size(0,y+8);}
    void LoadItems(bool force){if(store==null)return;current.Visible=done.Visible=!assistantView;ask.Text=assistantView?"Refresh work list":"Ask Quinn to update";if(assistantView){LoadAssistant();return;}try{var loaded=store.Read();string key=AppData.Json.Serialize(loaded)+showDone;if(!force&&previous==key)return;previous=key;document=loaded;rows.Enabled=current.Enabled=done.Enabled=ask.Enabled=true;summary.Text=loaded.updatedAt==null?"Local checklist · no items saved yet":"Saved "+AgentFeed.Stamp(loaded.updatedAt)+" · revision "+loaded.revision;current.Text="Current ("+loaded.items.Count(i=>i.state=="current")+")";done.Text="Done ("+loaded.items.Count(i=>i.state=="done")+")";footnote.Text=showDone?"Uncheck a Done item to restore it. Requests are copied, not sent.":"Copies a request; send it to Quinn in chat.";current.BackColor=showDone?Color.FromArgb(56,56,56):Color.FromArgb(69,69,69);done.BackColor=showDone?Color.FromArgb(69,69,69):Color.FromArgb(56,56,56);rows.SuspendLayout();foreach(Control control in rows.Controls.Cast<Control>().ToArray())control.Dispose();var selected=loaded.items.Where(i=>i.state==(showDone?"done":"current")).ToList();if(selected.Count==0)rows.Controls.Add(new Label{Text=showDone?"Completed items will be kept here.":"No current work listed. Ask Quinn to update the checklist.",Height=70,ForeColor=DashboardForm.Muted,Padding=new Padding(8),UseMnemonic=false});foreach(var item in selected){long revision=loaded.revision;string id=item.id;var row=new Panel{Height=String.IsNullOrEmpty(item.details)?70:104,BackColor=DashboardForm.Surface};var check=new CheckBox{Checked=showDone,Left=12,Top=14,Width=24,Height=24,AccessibleName=(showDone?"Restore ":"Complete ")+item.title,ForeColor=DashboardForm.Ink,BackColor=DashboardForm.Surface};row.Controls.Add(check);var name=new Label{Text=item.title,Left=44,Top=10,Height=38,ForeColor=DashboardForm.Ink,UseMnemonic=false,AutoEllipsis=true};row.Controls.Add(name);string project=String.IsNullOrEmpty(item.projectPath)?"":Path.GetFileName(item.projectPath.TrimEnd('\\','/'));var meta=new Label{Text=project+(showDone?" · Done "+AgentFeed.Stamp(item.completedAt):""),Left=44,Top=48,Height=20,ForeColor=DashboardForm.Muted,UseMnemonic=false,AutoEllipsis=true};row.Controls.Add(meta);var detail=new Label{Text=item.details,Left=44,Top=71,Height=28,ForeColor=DashboardForm.Muted,UseMnemonic=false,AutoEllipsis=true};row.Controls.Add(detail);row.Resize+=(s,e)=>name.Width=meta.Width=detail.Width=Math.Max(70,row.Width-56);check.CheckedChanged+=(s,e)=>{try{store.Complete(revision,id,check.Checked);}catch(Exception error){if(!testing)MessageBox.Show(FindForm(),error.Message,"Current work",MessageBoxButtons.OK,MessageBoxIcon.Information);}LoadItems(true);};rows.Controls.Add(row);}rows.ResumeLayout();PositionRows();}catch{previous=null;document=null;summary.Text="Checklist unavailable. Existing data was not changed.";foreach(Control control in rows.Controls.Cast<Control>().ToArray())control.Dispose();rows.Controls.Add(new Label{Text="The saved checklist could not be read. Checkoffs are disabled until it is valid again.",Height=100,ForeColor=DashboardForm.Muted,Padding=new Padding(8),UseMnemonic=false});rows.Enabled=current.Enabled=done.Enabled=ask.Enabled=false;PositionRows();}}
    void LoadAssistant(){
        previous=null;rows.AutoScrollMinSize=Size.Empty;rows.AutoScrollPosition=Point.Empty;rows.Enabled=ask.Enabled=true;
        foreach(Control control in rows.Controls.Cast<Control>().ToArray())control.Dispose();
        try{var work=AssistantWorkSource.Read(assistantProfile??AppData.Root);summary.Text="Maintained by Quinn - refreshed "+DateTime.Now.ToString("g");
            var text=new TextBox{Text=work.Text,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,WordWrap=true,BackColor=DashboardForm.Surface,ForeColor=DashboardForm.Ink,BorderStyle=BorderStyle.None,Dock=DockStyle.Fill,Font=Font};
            rows.Controls.Add(text);footnote.Text="Say: update the work list. Source: "+work.Path;
        }catch(Exception error){summary.Text="Work list unavailable";rows.Controls.Add(new Label{Text=error.Message,Height=100,ForeColor=DashboardForm.Muted,UseMnemonic=false});footnote.Text="Refresh after the source is available. Your checklist is separate.";}
        Position();
    }
    internal void CheckAssistantViews(List<Entry> entries){
        testing=true;
        assistantProfile=Path.Combine(AppData.Root,".dev","Review","AssistantWorkTests");
        Directory.CreateDirectory(Path.Combine(assistantProfile,".local"));
        string source=Path.Combine(assistantProfile,"work.txt"),config=Path.Combine(assistantProfile,".local","current-work-source.json"),checklist=Path.Combine(assistantProfile,".local","current-work.json");
        File.WriteAllText(source,"CURRENT WORK\r\nTwitch alerts - next after overlays.");
        File.WriteAllText(config,AppData.Json.Serialize(new AssistantWorkSource{schemaVersion=1,path=source}));
        if(File.Exists(checklist))File.Delete(checklist);
        store=new ChecklistStore(checklist,entries);store.Upsert(new WorkPatch{expectedRevision=0,id="assistant-regression-fixture",title="Personal fixture"});
        string before=File.ReadAllText(checklist);
        using(var host=new Form{Size=new Size(460,660),StartPosition=FormStartPosition.Manual,Location=new Point(-32000,-32000)}){
            Dock=DockStyle.Fill;host.Controls.Add(this);host.Show();Application.DoEvents();
            assistant.PerformClick();
            var text=rows.Controls.OfType<TextBox>().Single();
            if(!text.ReadOnly||!text.Text.Contains("Twitch alerts"))throw new Exception("Assistant source did not display read-only.");
            File.WriteAllText(source,"Updated work fixture");ask.PerformClick();
            if(rows.Controls.OfType<TextBox>().Single().Text!="Updated work fixture")throw new Exception("Assistant Refresh did not reread.");
            personal.PerformClick();if(!rows.Controls.OfType<Panel>().Any())throw new Exception("Personal checklist did not open.");
            assistant.PerformClick();File.Delete(source);ask.PerformClick();
            if(rows.Controls.OfType<TextBox>().Any()||summary.Text!="Work list unavailable")throw new Exception("Missing source left stale work.");
            File.WriteAllText(config,"{invalid");ask.PerformClick();
            if(rows.Controls.OfType<TextBox>().Any())throw new Exception("Invalid configuration left stale work.");
            personal.PerformClick();if(!rows.Controls.OfType<Panel>().Any())throw new Exception("Source failure blocked checklist.");
            if(File.ReadAllText(checklist)!=before)throw new Exception("Assistant interactions changed checklist bytes.");
            File.WriteAllText(config,AppData.Json.Serialize(new AssistantWorkSource{schemaVersion=1,path=source}));
            File.WriteAllText(source,String.Join("\r\n",Enumerable.Repeat("Verified work fixture with enough text to scroll.",120)));
            assistant.PerformClick();
            foreach(var size in new[]{new Size(380,300),new Size(460,660),new Size(700,800)}){host.Size=size;Application.DoEvents();host.Invalidate(true);host.Update();using(var image=new Bitmap(host.Width,host.Height))host.DrawToBitmap(image,new Rectangle(Point.Empty,host.Size));}
            host.Controls.Remove(this);host.Close();
        }
        testing=false;
        Console.WriteLine("Assistant UI regression passed: real button events, read-only content, Refresh reread, missing/invalid source handling, checklist navigation, unchanged checklist bytes, multi-size paints and long text.");
    }
    internal void ShowDone(){assistantView=false;showDone=true;LoadItems(true);}
    internal void CheckViews(List<Entry> entries){testing=true;assistantView=false;string path=Path.Combine(AppData.Root,".dev","Review","ChecklistTests","ui-work-test.json");Directory.CreateDirectory(Path.GetDirectoryName(path));if(File.Exists(path))File.Delete(path);store=new ChecklistStore(path,entries);store.Upsert(new WorkPatch{expectedRevision=0,id="ui-fixture",title="Isolated UI fixture"});LoadItems(true);var check=rows.Controls[0].Controls.OfType<CheckBox>().Single();check.Checked=true;if(store.Read().items[0].state!="done"||rows.Controls.OfType<Panel>().Any())throw new Exception("Checkoff did not leave Current.");done.PerformClick();if(!rows.Controls.OfType<Panel>().Any())throw new Exception("Done history was not shown.");rows.Controls[0].Controls.OfType<CheckBox>().Single().Checked=false;current.PerformClick();if(!rows.Controls.OfType<Panel>().Any()||new ChecklistStore(path,entries).Read().items[0].state!="current")throw new Exception("Restore/restart persistence failed.");File.WriteAllText(path,"{invalid-after-load");rows.Controls[0].Controls.OfType<CheckBox>().Single().Checked=true;if(rows.Enabled||current.Enabled||done.Enabled||ask.Enabled||rows.Controls.OfType<Panel>().Any()||File.ReadAllText(path)!="{invalid-after-load")throw new Exception("Invalid-after-load left an apparent saved checkoff.");Reload(entries);testing=false;Console.WriteLine("Checklist UI checks passed: invalid-after-load disables stale actions; checkoff leaves Current, remains in Done, restores and persists on reopen. Live checklist unchanged.");}
    void Ask(){if(assistantView){LoadItems(true);return;}if(store==null)return;try{document=store.Read();}catch(Exception error){MessageBox.Show(FindForm(),error.Message,"Current work",MessageBoxButtons.OK,MessageBoxIcon.Warning);return;}using(var dialog=new Form{Text="Ask Quinn to update",Size=new Size(620,410),MinimumSize=new Size(500,350),StartPosition=FormStartPosition.CenterParent,BackColor=DashboardForm.Background,ForeColor=DashboardForm.Ink,Font=Font,ShowInTaskbar=false,MinimizeBox=false,MaximizeBox=false}){var label=new Label{Text="Copy this request, then paste and send it in Quinn’s chat.",Dock=DockStyle.Top,Height=58,Padding=new Padding(20),ForeColor=DashboardForm.Ink};dialog.Controls.Add(label);var text=new TextBox{Text=ChecklistStore.Request(document),Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill,BackColor=DashboardForm.Surface,ForeColor=DashboardForm.Ink,BorderStyle=BorderStyle.FixedSingle};dialog.Controls.Add(text);text.BringToFront();var footer=new Panel{Dock=DockStyle.Bottom,Height=66,Padding=new Padding(16)};dialog.Controls.Add(footer);var copy=DashboardForm.LinkButton("Copy request");copy.SetBounds(16,14,140,38);copy.Click+=(s,e)=>{try{Clipboard.SetText(text.Text);label.Text="Copied. Paste and send it in Quinn’s chat; nothing was sent automatically.";}catch{label.Text="Copy failed. Select the request text and copy it manually.";}};footer.Controls.Add(copy);var close=DashboardForm.LinkButton("Close");close.SetBounds(440,14,110,38);close.Anchor=AnchorStyles.Top|AnchorStyles.Right;close.DialogResult=DialogResult.Cancel;footer.Controls.Add(close);dialog.CancelButton=close;dialog.ShowDialog(FindForm());}}
    protected override void Dispose(bool disposing){if(disposing){timer.Stop();timer.Dispose();}base.Dispose(disposing);}
}




// Read-only projection of the existing rolling work list; never writes checklist or status data.
internal sealed class AssistantWorkSource {
    public int schemaVersion {get;set;} public string path {get;set;}
    internal string Path,Text;
    internal static AssistantWorkSource Read(string profile){
        string config=System.IO.Path.Combine(profile,".local","current-work-source.json");
        string source=null;
#if WPF_REBUILD
        string managed=DashboardData.WorkPath(profile);
        if(File.Exists(managed))source=managed;
        else
#endif
        if(File.Exists(config)){
            if(new FileInfo(config).Length>16384)throw new IOException("Work source configuration is too large.");
            var setting=AppData.Json.Deserialize<AssistantWorkSource>(File.ReadAllText(config));
            if(setting==null||setting.schemaVersion!=1||String.IsNullOrWhiteSpace(setting.path)||!System.IO.Path.IsPathRooted(setting.path))throw new IOException("Invalid work source configuration. Use schemaVersion 1 and an absolute text-file path.");
            source=System.IO.Path.GetFullPath(setting.path);
        }
        if(String.IsNullOrWhiteSpace(source))throw new IOException("Choose your Agent tasks text file in Settings > Tasks.");
        if(!System.IO.Path.GetExtension(source).Equals(".txt",StringComparison.OrdinalIgnoreCase)&&!System.IO.Path.GetExtension(source).Equals(".md",StringComparison.OrdinalIgnoreCase))throw new IOException("Work source must be a .txt or .md file.");
        using(var stream=new FileStream(source,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){
            if(stream.Length>1024*1024)throw new IOException("Work list is too large (maximum 1 MiB).");
            using(var reader=new StreamReader(stream)){return new AssistantWorkSource{Path=source,Text=reader.ReadToEnd()};}
        }
    }
}
